"""Build expected/paper_values.json as an exact extraction of the numbers printed in the paper (v10 text).

Every value is parsed from the paper text (not typed by hand); its decimals are the printed decimals, and
'where' names the place it is printed. Quantities that are printed but cannot be regenerated by the archive
go to printed_not_checked with the reason. Quantities the archive checks that are NOT printed are kept in a
separate block (printed: false) so the v1.0.0 regression coverage is not lost, and are labelled as such.
usage: python ci/extract_paper_values.py <manuscript text file> .
(maintainers; the manuscript text is not part of this repository, its sha256 is recorded in the output)
"""
import hashlib
import json
import re
import sys
from pathlib import Path

paper_path, repo = Path(sys.argv[1]), Path(sys.argv[2])
raw = paper_path.read_bytes()
T = raw.decode("utf-8").replace(chr(13) + chr(10), chr(10))
man = json.loads((repo / "data/corpora/manifest.json").read_text(encoding="utf-8"))
ids = [d["id"] for d in man["datasets"]]
V = {}


def num(s):
    return float(s.replace("−", "-").replace(",", ""))


def dec(s):
    s = s.replace(",", "")
    return len(s.split(".")[1]) if "." in s else 0


def put(key, s, where, printed=True):
    v = num(s)
    d = dec(s)
    if key in V:
        assert round(V[key]["value"], min(d, V[key]["decimals"])) == round(v, min(d, V[key]["decimals"])), (key, s, V[key])
        if d <= V[key]["decimals"]:
            V[key]["where"] += "; " + where
            return
        where = V[key]["where"] + "; " + where
    V[key] = {"value": int(v) if d == 0 else v, "decimals": d, "printed": printed, "where": where}


def find(pattern, flags=0):
    m = re.search(pattern, T, flags)
    assert m, pattern
    return m


# ---- Table 1 rows (in manifest order)
rows = re.findall(r"^(.+?) \| ([\d,]+) \| (\d+) \(([\d.]+)\) \| ([−\d.]+) \(([\d.]+)\) \| ([−\d.]+) \| ([−\d.]+)$", T, re.M)
assert len(rows) == 19, len(rows)
for i, (name, rec, rel, prev, sm, ssd, nb, svm) in zip(ids, rows):
    w = f"Table 1, {name}"
    put(f"records[{i}]", rec, w)
    put(f"relevant[{i}]", rel, w)
    put(f"prevalence_pct[{i}]", prev, w)
    put(f"screen_wss95[{i}]", sm, w)
    put(f"screen_wss95_sd[{i}]", ssd, w)
    put(f"asreview_nb_wss95[{i}]", nb, w)
    put(f"asreview_svm_wss95[{i}]", svm, w)
m = find(r"^Mean \(19 datasets\) \|  \|  \| ([\d.]+) \| ([\d.]+) \| ([\d.]+)$", re.M)
put("screen_mean_all", m.group(1), "Table 1, mean row")
put("asreview_nb_mean", m.group(2), "Table 1, mean row")
put("asreview_svm_mean", m.group(3), "Table 1, mean row")

# ---- Abstract
m = find(r"WSS@95\) was ([\d.]+) \(range ([−\d.]+) to ([\d.]+)\)")
put("screen_mean_all", m.group(1), "Abstract, Results")
put("screen_min", m.group(2), "Abstract, Results")
put("screen_max", m.group(3), "Abstract, Results")
m = find(r"Naive Bayes configuration \(\+([\d.]+); p = ([\d.]+)\)")
put("mean_diff_vs_nb", m.group(1), "Abstract, Results")
put("wilcoxon_p_vs_nb", m.group(2), "Abstract, Results")
m = find(r"default SVM configuration \(−([\d.]+); p = ([\d.]+)\)")
put("mean_diff_vs_svm", "-" + m.group(1), "Abstract, Results")
put("wilcoxon_p_vs_svm", m.group(2), "Abstract, Results")
m = find(r"on (\d+) publicly available labelled datasets using (\d+) seeds")
put("n_datasets", m.group(1), "Abstract, Methods")
put("screen_seeds", m.group(2), "Abstract, Methods")

# ---- Methods (benchmark)
m = find(r"They range from ([\d,]+) to ([\d,]+) records, with ([\d.]+)% to (\d+)% of records relevant")
put("records_min", m.group(1), "Methods, Benchmark")
put("records_max", m.group(2), "Methods, Benchmark")
put("prevalence_min_pct", m.group(3), "Methods, Benchmark")
put("prevalence_max_pct", m.group(4), "Methods, Benchmark")
find(r"same files with three seeds")
V["asreview_seeds"] = {"value": 3, "decimals": 0, "printed": True, "where": "Methods, Benchmark ('three seeds'); Table 1 caption"}

# ---- Results text
m = find(r"Mean WSS@95 for Screen was ([\d.]+) \(median ([\d.]+)\): ([\d.]+) for the Cohen datasets and ([\d.]+) for the SYNERGY")
put("screen_mean_all", m.group(1), "Results para 1")
put("screen_median_all", m.group(2), "Results para 1")
put("screen_mean_cohen", m.group(3), "Results para 1")
put("screen_mean_synergy", m.group(4), "Results para 1")
m = find(r"On average, (\d+)%, (\d+)% and (\d+)% of the relevant records were found after screening 10%, 20% and 50%")
put("recall_at_10pct_pct", m.group(1), "Results para 1 (Figure 9)")
put("recall_at_20pct_pct", m.group(2), "Results para 1 (Figure 9)")
put("recall_at_50pct_pct", m.group(3), "Results para 1 (Figure 9)")
m = find(r"Naive Bayes configuration had a mean WSS@95 of ([\d.]+)\. Screen was higher on (\d+) of 19 datasets, .*?\(W = (\d+), p = ([\d.]+)\)")
put("asreview_nb_mean", m.group(1), "Results para 2")
put("wins_vs_nb", m.group(2), "Results para 2")
put("wilcoxon_W_vs_nb", m.group(3), "Results para 2")
put("wilcoxon_p_vs_nb", m.group(4), "Results para 2")
m = find(r"default SVM configuration had a mean of ([\d.]+), and Screen was higher on only (\d+) of 19 datasets \(mean difference −([\d.]+); Wilcoxon W = (\d+), p = ([\d.]+)\)")
put("asreview_svm_mean", m.group(1), "Results para 2")
put("wins_vs_svm", m.group(2), "Results para 2")
put("mean_diff_vs_svm", "-" + m.group(3), "Results para 2")
put("wilcoxon_W_vs_svm", m.group(4), "Results para 2")
put("wilcoxon_p_vs_svm", m.group(5), "Results para 2")
m = find(r"found (\d+) of (\d+) reformatted duplicates \(precision ([\d.]+)\)\. However, only (\d+) of (\d+) author-labelled duplicates")
put("dedup_reformatted_detected", m.group(1), "Results para 3")
put("dedup_reformatted_injected", m.group(2), "Results para 3")
put("dedup_reformatted_precision", m.group(3), "Results para 3")
put("dedup_nagtegaal_detected", m.group(4), "Results para 3")
put("dedup_nagtegaal_gold_duplicates", m.group(5), "Results para 3")
m = find(r"processed ([\d,]+) records in ([\d.]+) seconds")
assert m.group(1) == "100,000"

# ---- Table 2
m = find(r"Reformatted duplicates \((\d+) ACE-inhibitor records, DOI removed, title altered, among ([\d,]+) originals\) \| (\d+)/(\d+) found; recall ([\d.]+); precision ([\d.]+); F1 ([\d.]+)")
put("dedup_reformatted_injected", m.group(1), "Table 2")
put("dedup_reformatted_originals", m.group(2), "Table 2")
put("dedup_reformatted_detected", m.group(3), "Table 2")
put("dedup_reformatted_recall", m.group(5), "Table 2")
put("dedup_reformatted_precision", m.group(6), "Table 2")
put("dedup_reformatted_f1", m.group(7), "Table 2")
m = find(r"Author-labelled duplicates \(Nagtegaal dataset \[16\], ([\d,]+) records\) \| (\d+)/(\d+) found \(recall ([\d.]+)\); (\d+) further flags not verified")
put("dedup_nagtegaal_records", m.group(1), "Table 2")
put("dedup_nagtegaal_detected", m.group(2), "Table 2")
put("dedup_nagtegaal_gold_duplicates", m.group(3), "Table 2")
put("dedup_nagtegaal_recall", m.group(4), "Table 2")
put("dedup_nagtegaal_flagged_not_in_gold", m.group(5), "Table 2")
m = find(r"Blocked vs exhaustive comparison \(([\d,]+) records\) \| Identical \((\d+)/(\d+) duplicates\)")
put("dedup_blocked_vs_brute_records", m.group(1), "Table 2")
put("dedup_blocked_vs_brute_blocked", m.group(2), "Table 2 ('Identical (12/12)')")
put("dedup_blocked_vs_brute_brute", m.group(3), "Table 2 ('Identical (12/12)')")
V["dedup_blocked_vs_brute_brute_only"] = {"value": 0, "decimals": 0, "printed": True, "where": "Table 2 ('Identical'): exhaustive-only = 0"}
V["dedup_blocked_vs_brute_blocked_only"] = {"value": 0, "decimals": 0, "printed": True, "where": "Table 2 ('Identical'): blocked-only = 0"}
m = find(r"Run time, blocked pass \(([\d,]+) synthetic records\) \| ([\d.]+) s \(([\d,]+) comparisons\)")
put("dedup_blocked_comparisons[n=100000]", m.group(3), "Table 2")

# derived but printed-equivalent: false positives / total flagged follow from 183/200 and precision 0.984 only jointly,
# so they are kept as unprinted checks below.
unprinted = {
    "dedup_reformatted_false_positives": 3, "dedup_reformatted_total_flagged": 186,
    "buscar_never_fired": 14, "median_diff_vs_nb": 0.014, "median_diff_vs_svm": -0.018,
}
old = json.loads((repo / "expected/paper_values.json").read_text(encoding="utf-8"))["values"]
for k, v in unprinted.items():
    assert round(old[k]["value"], old[k]["decimals"]) == v, k
    V[k] = {"value": v, "decimals": old[k]["decimals"], "printed": False, "where": "not printed in the paper (canonical v1.0.0 value, kept as a regression check)"}

# every old pinned value must agree with the extraction at the coarser precision (no silent changes)
for k, spec in old.items():
    if k in V:
        d = min(spec["decimals"], V[k]["decimals"])
        assert round(spec["value"], d) == round(V[k]["value"], d), (k, spec, V[k])

printed_not_checked = {
    "dedup_runtime_100k": {"printed": "6.6 s (Results para 3; Table 2)", "reason": ("machine-dependent wall time, and not traceable to any archived run: the canonical Docker run "
 "(CI run 37199331989) took 19.2 s and the Linux, Windows and macOS runs of the same CI run 11.9, 12.9 and 16.2 s; a 4-CPU re-run on a "
 "second machine took 14.7 s. Each run now records its machine and times in outputs/<protocol>/<mode>/machine.json and table2_dedup.")},
    "unit_and_browser_tests": {"printed": "36 unit tests, 49 browser tests (Results para 1)", "reason": "these are allmeta's test suites, not part of this archive; the count belongs to the allmeta commit named in the paper's software availability"},
    "kappa_example": {"printed": "kappa = 0.836 over 70 dual-decided records (Figure 3)", "reason": "illustrative screenshot of an example project (docs/screenshots/make_sample.py), not a benchmark result"},
    "auc_example": {"printed": "AUC 0.91 (Figure 4)", "reason": "illustrative screenshot value, not a benchmark result"},
    "example_project_counts": {"printed": "312 records, 17 duplicates (Figure 1)", "reason": "illustrative example project used for the screenshots"},
    "dedup_text_precision_2dp": {"printed": "precision 0.98 (Results para 3)", "reason": "same quantity as Table 2's 0.984, which is checked at 3 dp"},
}
doc = {
    "source": ("Exact extraction of the numbers printed in the F1000Research manuscript (text version v10, sha256 "
               + hashlib.sha256(raw).hexdigest() + "), parsed from the text by a script, each at its printed number of decimals, "
               "with the place it is printed. These are the protocol v1.0.0 results (canonical Docker run, commit 7712c15; "
               "bit-identical to native Linux, Windows and macOS runs). A reproduced number passes only if it rounds to exactly "
               "the printed value. Entries with printed=false are not in the paper; they are canonical v1.0.0 values kept as "
               "regression checks. printed_not_checked lists printed numbers this archive cannot regenerate, with the reason."),
    "protocol": "v1.0.0",
    "values": V,
    "printed_not_checked": printed_not_checked,
}
(repo / "expected/paper_values.json").write_text(json.dumps(doc, indent=1, ensure_ascii=False) + "\n", encoding="utf-8", newline="\n")
print(len(V), "values;", sum(1 for v in V.values() if v["printed"]), "printed;", len(printed_not_checked), "printed but not checked")
